mapper.select:
SELECT m.id AS meter_id, m.meter_code AS meter_code, m.meter_name AS meter_name, m.device_id AS device_id, d.name AS device_name, m.enterprise_id AS enterprise_id, m.energy_type_id AS energy_type_id, FLOOR(86400 / GREATEST(m.collect_interval_seconds, 1)) AS expected_count FROM energy_meter m LEFT JOIN energy_device d ON d.id = m.device_id AND d.deleted = 0 WHERE m.deleted = 0 AND m.status = 1 AND (m.install_time IS NULL OR m.install_time < DATE_ADD(#{date}, INTERVAL 1 DAY))
AND m.enterprise_id = #{enterpriseId}
ORDER BY m.id

SELECT r.meter_id AS meter_id, COUNT(*) AS valid_count FROM energy_raw_data r WHERE r.deleted = 0 AND r.quality <> 3 AND r.collect_time >= #{date} AND r.collect_time < DATE_ADD(#{date}, INTERVAL 1 DAY)
AND r.enterprise_id = #{enterpriseId}
GROUP BY r.meter_id
